css:
.input-add-friend {
  width: 17em;
  height: 11em;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  --color: rgb(169, 116, 255);
  --background-color: rgb(36, 34, 39);
}

.input-add-friend .input-add-friend-title {
  display: flex;
  align-self: flex-start;
  margin-left: 0.5em;
}
.input-add-friend-title {
  width: 8em;
  height: 2em;
  background-color: var(--background-color);
  color: white;
  display: flex;
  justify-content: center;
  font-weight: bold;
  font-family: monospace, sans-serif;
  box-shadow:
    -0.05em 0em var(--color),
    -0.05em -0.05em var(--color),
    0.05em -0.05em var(--color);
  position: relative;
  z-index: 1;
  align-items: center;
}
.input-add-friend-input {
  width: 16em;
  height: 8em;
  background-color: var(--background-color);

  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  gap: 1em;
  font-weight: bold;
  box-shadow:
    -0.05em 0em var(--color),
    -0.05em 0.05em var(--color),
    0.05em 0.05em var(--color),
    0.05em -0.05em var(--color),
    0em 0em 2.5em 0em rgb(121, 174, 30, 0.15);
  position: relative;
  z-index: 0;
  animation: change-box-shadow 5s linear infinite;
}

@keyframes change-box-shadow {
  0% {
    box-shadow:
      -0.05em 0em var(--color),
      -0.05em 0.05em var(--color),
      0.05em 0.05em var(--color),
      0.05em -0.05em var(--color),
      0em 0em 2.5em 0em rgb(169, 116, 255, 0);
  }
  50% {
    box-shadow:
      -0.05em 0em var(--color),
      -0.05em 0.05em var(--color),
      0.05em 0.05em var(--color),
      0.05em -0.05em var(--color),
      0em 0em 2.5em 0em rgb(169, 116, 255, 0.25);
  }
  100% {
    box-shadow:
      -0.05em 0em var(--color),
      -0.05em 0.05em var(--color),
      0.05em 0.05em var(--color),
      0.05em -0.05em var(--color),
      0em 0em 2.5em 0em rgb(169, 116, 255, 0);
  }
}
.input-add-friend-input input {
  width: 16em;
  height: 2.5em;

  border: solid 0.5em transparent;
  font-family: monospace, sans-serif;
  color: var(--background-color);
  font-weight: bold;
  outline: none;
  padding-left: 3.5em;
  letter-spacing: 1em;
  background-color: transparent;
  position: relative;
  z-index: 4;
}

.input::placeholder {
  color: var(--background-color);
  font-weight: bold;
  font-family: monospace, sans-serif;
}

.input-add-friend-checkbox:hover + label {
  opacity: 75%;
}

.input-add-friend-checkbox:hover + label p {
  font-size: 14px;
  transition: all 0.25s ease-in-out;
}

.input-add-friend-checkbox + label {
  width: 13.25em;
  height: 2.25em;
  border: solid 0.5em var(--color);
  background-color: var(--color);
  font-family: monospace, sans-serif;
  color: var(--background-color);
  font-weight: bold;
  outline: none;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all 0.25s ease-in-out;
}

.input-add-friend svg {
  position: absolute;
  top: -2.25em;
  right: 0em;
}

.input-add-friend-checkbox:active + label {
  background-color: white;
  border: white;
}

.input-add-friend:has(.input-add-friend-checkbox:checked) {
  filter: hue-rotate(-120deg);
  transition: all 0.25s ease-in-out;
}

.input-add-friend-checkbox:checked ~ svg {
  animation: jumpicon 0.75s infinite linear;
  animation-iteration-count: 1;
}

@keyframes jumpicon {
  0% {
    top: -2.25em;
    transform: rotate(0deg) scale(1);
  }
  25% {
    top: -2.5em;
    transform: rotate(0deg) scale(1.15);
  }
  50% {
    top: -2.5em;
    transform: rotate(10deg) scale(1.15);
  }
  75% {
    top: -2.5em;
    transform: rotate(-10deg) scale(1.15);
  }
  95% {
    transform: rotate(0deg) scale(1);
  }
  100% {
    top: -2.25em;
    transform: rotate(0deg) scale(1);
  }
}

.input-add-friend-text {
  color: var(--background-color);
  position: absolute;
  letter-spacing: 0.85em;
  top: 1.65em;
  left: 5.25em;
  z-index: 3;
}

.input-add-friend-input-behind {
  width: 13.25em;
  height: 2.25em;
  top: 1.35em;
  font-family: monospace, sans-serif;
  color: var(--background-color);
  font-weight: bold;
  background-color: rgb(255, 255, 255);
  position: absolute;
  z-index: 2;
}
